/* Local 1.0: regional configuration and accessible inbox sizing. */
function readingRegions(){return state.data?.regions||[{id:'national',name:'全国'},{id:'guangdong',name:'广东'}]}
function areaName(id){return (state.data?.region_catalog||state.sourceConfig?.catalog||readingRegions()).find(r=>r.id===id)?.name||(id==='unassigned'?'未指定地区':id==='national'?'全国':id==='guangdong'?'广东':id)}
function archiveFilters(){const regions=[...new Set([...readingRegions().map(r=>r.id),...(state.library?.region_options||[])])];return `<form id="archive-filters" class="archive-filters"><label>起始日期<input type="date" name="from" aria-label="档案起始日期" value="${esc(state.archiveFrom||'')}"></label><label>截止日期<input type="date" name="to" aria-label="档案截止日期" value="${esc(state.archiveTo||'')}"></label><label>地区<select name="region" aria-label="档案地区"><option value="all">全部地区</option>${regions.map(r=>`<option value="${esc(r)}" ${state.archiveRegion===r?'selected':''}>${esc(areaName(r))}</option>`).join('')}</select></label><button class="btn primary">查找</button><button type="button" class="btn" data-release="reset-filters">重置</button></form>`}
function collectionButton(){return `<button class="btn primary update-edition" data-action="collect" ${state.data?.job.running?'disabled':''}>${uiIcon('arrow_clockwise')}${state.data?.job.running?'正在更新…':'一键更新本期材料'}</button>`}
function inboxSplitter(){return `<div id="inbox-splitter" role="separator" tabindex="0" aria-label="调整待阅列表宽度" aria-orientation="vertical" aria-valuemin="260" aria-valuemax="620" aria-valuenow="368" title="左右拖动调整；也可用方向键或阅读显示中的宽度控件"><span></span></div>`}
function setInboxWidth(value,persist=true){if(window.innerWidth<=760)return;const nav=parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--nav-width'))||184,max=Math.max(260,Math.min(620,window.innerWidth-nav-320)),width=Math.max(260,Math.min(max,Number(value)||368));document.documentElement.style.setProperty('--inbox-width',width+'px');const bar=$('#inbox-splitter');if(bar){bar.setAttribute('aria-valuenow',width);bar.setAttribute('aria-valuemax',max)}for(const range of $$('[data-inbox-width]')){range.max=max;range.value=width}if(persist)try{localStorage.setItem('zhuyi-v1-inbox-width',width)}catch{}}
function restoreInboxWidth(){let width=368;try{width=Number(localStorage.getItem('zhuyi-v1-inbox-width'))||368}catch{}setInboxWidth(width,false)}
let inboxDrag=null;
document.addEventListener('pointerdown',e=>{const b=e.target.closest('#inbox-splitter');if(!b||e.button!==0)return;e.preventDefault();b.setPointerCapture(e.pointerId);inboxDrag={id:e.pointerId,x:e.clientX,width:parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--inbox-width'))};document.body.classList.add('resizing-inbox')});
document.addEventListener('pointermove',e=>{if(inboxDrag?.id===e.pointerId)setInboxWidth(inboxDrag.width+e.clientX-inboxDrag.x)});
for(const event of ['pointerup','pointercancel','lostpointercapture'])document.addEventListener(event,()=>{inboxDrag=null;document.body.classList.remove('resizing-inbox')});
document.addEventListener('keydown',e=>{if(e.target.id!=='inbox-splitter')return;const width=Number(e.target.getAttribute('aria-valuenow'));if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();setInboxWidth(e.key==='Home'?260:e.key==='End'?620:width+(e.key==='ArrowLeft'?-16:16))}});
window.addEventListener('resize',restoreInboxWidth);
document.addEventListener('DOMContentLoaded',restoreInboxWidth);
document.addEventListener('input',e=>{if(e.target.matches('[data-inbox-width]'))setInboxWidth(e.target.value);const f=e.target.closest('#source-form');if(f){f.dataset.token='';f.querySelector('[data-source-save]').disabled=true;$('#source-test-result').textContent='参数已修改，请测试来源。'}});
function probeResult(r){return `<p class="${r.ok?'test-pass':'test-fail'}">${esc(r.message||(r.ok?'测试通过':'测试未通过'))}<small>${esc(r.tested_at||'')} · 发现 ${r.candidates||0} 条候选</small></p>${(r.samples||[]).map(s=>`<div class="probe-sample"><a href="${safeUrl(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title||s.url)}</a><small>${s.ok?'正文、日期可读取':esc(s.message||'解析失败')} · ${s.characters||0} 字${s.published?' · '+esc(s.published.slice(0,10)):''}</small></div>`).join('')}`}
async function renderSourceSettings(){const config=await api('/source-config');if(state.view!=='sources')return;state.sourceConfig=config;state.sources=config.sources;const report=state.data.edition?.report||[];
 $('#content').innerHTML=heading('设置',collectionButton())+settingsNavigation('sources')+`<div class="settings-intro"><h2>来源与采集</h2><p>按来源权重筛选材料，秘书仅在你提问时参与。</p></div><section class="panel"><div class="section-heading"><h2>阅读地区</h2><button class="btn" data-release="add-region">${uiIcon('plus')}新增省份</button></div><div class="region-chips">${config.regions.map(r=>`<span class="region-chip">${esc(r.name)}${r.id==='national'?'<small>固定</small>':`<button class="icon-button" data-release="delete-region" data-id="${r.id}" aria-label="删除${esc(r.name)}省份">${uiIcon('xmark')}</button>`}</span>`).join('')}</div></section><section class="panel"><div class="section-heading"><h2>采集来源</h2><button class="btn" data-release="add-source">${uiIcon('plus')}新增来源</button></div>${config.sources.map(s=>{const r=report.find(x=>x.id===s.id);let test={};try{test=JSON.parse(s.test_report||'{}')}catch{}return `<div class="source-row"><div><a href="${safeUrl(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.name)} ↗</a><small>${esc(areaName(s.region))} · 权重 ${s.rank}${s.builtin?' · 内置':''}</small></div><div><small>${r?`候选 ${r.found||0} · 入选 ${r.included||0}${r.error?' · '+esc(r.error):''}`:'尚无本期采集记录'}</small><small>${s.tested_at?`${test.ok?'测试通过':'测试未通过'} · ${fmt(s.tested_at)}`:'尚未测试'}</small></div><div class="actions"><button class="btn" data-release="test-source" data-id="${esc(s.id)}">测试</button>${s.builtin&&s.region==='national'?'':`<button class="icon-button" data-release="delete-source" data-id="${esc(s.id)}" aria-label="删除来源${esc(s.name)}">${uiIcon('trash')}</button>`}</div></div>`}).join('')}<div class="actions compose-actions"><button class="btn" data-action="uncertain">日期待核材料</button></div><p class="data-note">测试检查候选链接、文章正文与发布日期；网站变更后可重新测试。</p></section>`+sourceImportForm();
}
function sourceImportForm(){return `<section class="panel"><h2>导入原文</h2><form id="import-form"><div class="field"><label for="import-url">原文链接</label><input id="import-url" name="url" type="url" required placeholder="https://…"></div><details><summary>手动粘贴正文</summary><div class="field"><label for="import-title">标题</label><input id="import-title" name="title"></div><div class="field"><label for="import-date">发布时间</label><input id="import-date" name="published" type="datetime-local"></div><div class="field"><label for="import-body">正文</label><textarea id="import-body" name="body" rows="7"></textarea></div></details><button class="btn primary compose-actions">导入档案</button></form></section>`}
function sourceForm(addRegion){const c=state.sourceConfig,regions=addRegion?c.catalog.filter(r=>!c.regions.some(a=>a.id===r.id)):c.regions;if(!regions.length)return toast('所有省份均已添加');showDialog('#organize-dialog',addRegion?'新增省份及来源':'新增来源',`<form id="source-form" data-add-region="${addRegion}"><div class="field"><label for="source-region">${addRegion?'省份':'所属地区'}</label><select name="region" id="source-region">${regions.map(r=>`<option value="${r.id}">${esc(r.name)}</option>`).join('')}</select></div><div class="field"><label for="source-name">来源名称</label><input name="name" id="source-name" required maxlength="60" placeholder="如：浙江省人民政府政策栏目"></div><div class="field"><label for="source-url">栏目网址或 RSS 地址</label><input name="url" id="source-url" type="url" required placeholder="https://…"></div><div class="source-options"><div class="field"><label for="source-format">解析方式</label><select name="format" id="source-format"><option value="auto">自动识别</option><option value="html">网页栏目</option><option value="rss">RSS / Atom</option></select></div><div class="field"><label for="source-rank">权重（0 最高，10 最低）</label><input name="rank" id="source-rank" type="number" min="0" max="10" step="1" value="2" required></div></div><div id="source-test-result" role="status" aria-live="polite">先测试通过，再保存。</div><div class="actions compose-actions"><button type="button" class="btn" data-release="test-source-draft">测试来源</button><button class="btn primary" data-source-save disabled>${addRegion?'保存省份与来源':'保存来源'}</button></div></form>`)}
async function releaseAction(action,b){
 if(action==='reset-width'){setInboxWidth(368);return}
 if(action==='reset-filters'){state.archiveFrom=state.archiveTo='';state.archiveRegion='all';state.page=1;return renderLibrary()}
 if(action==='add-region'||action==='add-source')return sourceForm(action==='add-region');
 if(action==='test-source-draft'){const f=$('#source-form');if(!f.reportValidity())return;const values=Object.fromEntries(new FormData(f)),snapshot=JSON.stringify(values);f.dataset.token='';f.querySelector('[data-source-save]').disabled=true;b.disabled=true;$('#source-test-result').textContent='正在读取候选文章、正文与日期…';try{const r=await api('/test-source',values);if(!f.isConnected||JSON.stringify(Object.fromEntries(new FormData(f)))!==snapshot)return;$('#source-test-result').innerHTML=probeResult(r);f.dataset.token=r.ok?r.test_token:'';f.querySelector('[data-source-save]').disabled=!r.ok}catch(e){$('#source-test-result').textContent=e.message}finally{b.disabled=false}return}
 if(action==='test-source'){b.disabled=true;b.textContent='测试中…';try{const r=await api('/test-source',{id:b.dataset.id});if(state.view==='sources'){await renderSources();showDialog('#organize-dialog','来源测试',probeResult(r))}}finally{b.disabled=false;b.textContent='测试'}return}
 if(action==='delete-region'||action==='delete-source'){const region=action==='delete-region',item=(region?state.sourceConfig.regions:state.sources).find(s=>s.id===b.dataset.id);if(!await confirmAction('删除'+item.name+'？',region?'同时移除该省份的采集来源；已保存的文章、批注和文稿保留在档案室。':'仅删除此来源配置，已保存的材料保留。'))return;await api(region?'/regions':'/sources',{action:'delete',id:item.id});await load(false);if(!readingRegions().some(r=>r.id===state.region))state.region='national';await renderSources();toast('配置已更新');return}
}
document.addEventListener('click',e=>{const b=e.target.closest('[data-release]');if(b){e.preventDefault();releaseAction(b.dataset.release,b).catch(e=>toast(e.message))}});
document.addEventListener('submit',async e=>{const f=e.target;if(!['source-form','archive-filters'].includes(f.id))return;e.preventDefault();try{const v=Object.fromEntries(new FormData(f));if(f.id==='archive-filters'){if(v.from&&v.to&&v.from>v.to)return toast('起始日期不能晚于截止日期');state.archiveFrom=v.from;state.archiveTo=v.to;state.archiveRegion=v.region;state.page=1;state.selected?.clear();await renderLibrary()}else{const b=f.querySelector('[data-source-save]');b.disabled=true;try{await api(f.dataset.addRegion==='true'?'/regions':'/sources',{...v,test_token:f.dataset.token});$('#organize-dialog').close();await load(false);await renderSources();toast('来源已保存')}finally{b.disabled=!f.dataset.token}}}catch(err){toast(err.message)}});
